{"file_path": "/workspace/services/brief_dates.jac", "content": """"Shared brief-week date helpers: weekdays use this Monday, weekends look ahead to next Monday."""

import from datetime { date, datetime, timedelta }

"""Normalize a date or datetime to a plain date."""
def _as_date(day: date) -> date {
    if isinstance(day, datetime) {
        return day.date();
    }
    return day;
}

"""Monday of the week a brief on `day` covers."""
def brief_monday(day: date) -> date {
    d = _as_date(day);
    wd = d.weekday();
    if wd >= 5 {
        return d + timedelta(days=7 - wd);
    }
    return d - timedelta(days=wd);
}

"""Days between the brief Monday and `day` (negative on weekends)."""
def brief_day_index(day: date) -> int {
    d = _as_date(day);
    return (d - brief_monday(d)).days;
}

"""Spoken label naming the brief Monday, e.g. 'Monday, September 28, 2026'."""
def brief_week_label(day: date) -> str {
    m = brief_monday(day);
    return f"{m.strftime('%A, %B')} {m.day}, {m.year}";
}
"}

